cd /tmp/vally-eval-trial-lHtfuQ && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-11-25 tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
